  "about.hero.desc": {
    en: "Dedicated to guiding individuals and families toward a new life in Canada with integrity, expertise, and care.",
    fr: "Dédiés à guider les individus et les familles vers une nouvelle vie au Canada avec intégrité, expertise et attention.",
    vi: "Cam kết đồng hành cùng cá nhân và gia đình hướng tới cuộc sống mới tại Canada với chính trực, chuyên môn và tận tâm.",
  },
  "about.mission.label": { en: "Our Mission", fr: "Notre mission", vi: "Sứ mệnh" },
  "about.mission.title": { en: "Immigration Done Right", fr: "L'immigration bien faite", vi: "Di trú đúng cách" },
  "about.mission.p1": {
    en: "At Nuvia Immigration Consulting, we believe every immigration journey deserves honest guidance, meticulous preparation, and unwavering support. Founded by licensed Regulated Canadian Immigration Consultants, our firm was built on the principle that clients deserve transparency — not false promises.",
    fr: "Chez Nuvia Immigration Consulting, nous croyons que chaque parcours d'immigration mérite des conseils honnêtes, une préparation minutieuse et un soutien constant. Fondée par des consultants RCIC agréés, notre firme repose sur la transparence — pas de fausses promesses.",
    vi: "Tại Nuvia Immigration Consulting, chúng tôi tin rằng mỗi hành trình di trú xứng đáng được hướng dẫn trung thực, chuẩn bị kỹ lưỡng và hỗ trợ không ngừng. Được thành lập bởi tư vấn viên RCIC có giấy phép, chúng tôi xây dựng trên nguyên tắc minh bạch — không hứa hẹn sai.",
  },
  "about.mission.p2": {
    en: "We stay current with Canada's evolving immigration policies and leverage our deep knowledge of federal and provincial programs to craft strategies that give our clients the best possible outcome.",
    fr: "Nous restons à jour avec l'évolution des politiques d'immigration du Canada et utilisons notre connaissance approfondie des programmes fédéraux et provinciaux.",
    vi: "Chúng tôi cập nhật chính sách di trú Canada và tận dụng hiểu biết sâu về các chương trình liên bang và tỉnh bang để xây dựng chiến lược tốt nhất.",
  },
  "about.cred.1": { en: "Licensed RCIC in good standing with CICC", fr: "RCIC agréé en règle auprès du CCIC", vi: "RCIC có giấy phép và tuân thủ CICC" },
  "about.cred.2": { en: "Member of the Canadian Association of Professional Immigration Consultants (CAPIC)", fr: "Membre de l'Association canadienne des consultants professionnels en immigration (ACCPI)", vi: "Thành viên CAPIC" },
  "about.cred.3": { en: "Bound by the CICC Code of Professional Conduct", fr: "Lié au code de déontologie du CCIC", vi: "Tuân thủ Quy tắc ứng xử chuyên nghiệp CICC" },
  "about.cred.4": { en: "Professional liability insurance maintained", fr: "Assurance responsabilité professionnelle maintenue", vi: "Duy trì bảo hiểm trách nhiệm nghề nghiệp" },
  "about.cred.5": { en: "Continuing professional development completed annually", fr: "Formation professionnelle continue annuelle", vi: "Hoàn thành đào tạo chuyên môn hàng năm" },
  "about.values.label": { en: "Our Values", fr: "Nos valeurs", vi: "Giá trị cốt lõi" },
  "about.values.title": { en: "What Sets Us Apart", fr: "Ce qui nous distingue", vi: "Điều làm nên khác biệt" },
  "about.values.integrity.title": { en: "Integrity First", fr: "L'intégrité d'abord", vi: "Chính trực là trên hết" },
  "about.values.integrity.desc": {
    en: "We provide honest eligibility assessments. If a pathway isn't viable, we'll tell you — and explore alternatives that may work.",
    fr: "Nous fournissons des évaluations honnêtes. Si une voie n'est pas viable, nous vous le dirons et explorerons des alternatives.",
    vi: "Chúng tôi đánh giá trung thực. Nếu lộ trình không khả thi, chúng tôi sẽ nói rõ và tìm phương án thay thế.",
  },
  "about.values.client.title": { en: "Client-Centred Approach", fr: "Approche centrée sur le client", vi: "Lấy khách hàng làm trung tâm" },
  "about.values.client.desc": {
    en: "Your goals drive our strategy. We listen carefully, communicate clearly, and treat every case with the attention it deserves.",
    fr: "Vos objectifs orientent notre stratégie. Nous écoutons, communiquons clairement et traitons chaque dossier avec attention.",
    vi: "Mục tiêu của bạn định hướng chiến lược của chúng tôi. Lắng nghe, giao tiếp rõ ràng và chăm sóc từng hồ sơ.",
  },
  "about.values.compliance.title": { en: "Regulatory Compliance", fr: "Conformité réglementaire", vi: "Tuân thủ quy định" },
  "about.values.compliance.desc": {
    en: "We operate strictly within CICC regulations and IRCC requirements, ensuring your application meets the highest standards.",
    fr: "Nous opérons strictement selon les règlements du CCIC et les exigences de l'IRCC.",
    vi: "Chúng tôi tuân thủ nghiêm ngặt quy định CICC và yêu cầu IRCC, đảm bảo hồ sơ đạt tiêu chuẩn cao nhất.",
  },
  "about.rcic.label": { en: "Lead Consultant", fr: "Consultant principal", vi: "Tư vấn viên chính" },
